import { useContext } from 'react'
import { Navigate, Outlet, Route, Routes, BrowserRouter, useLocation } from 'react-router-dom'

// import { useTheme } from '@mui/material/styles'
// import { useMediaQuery } from '@mui/material'

import Disclaimer from "./Disclaimer"
import Navbar from "./Navbar"
import PopulationDataProvider, { PopulationDataContext } from "./contexts/PopulationData"
import PopulationPicker from "./PopulationPicker"
import ResultsDashboard from "./ResultsDashboard"
import SelectionPanel from "./SelectionPanel"


// Redirect unknown routes to /start, keeping the URL params
function RedirectToStart() {
  const { search } = useLocation()

  return <Navigate to={{ pathname: '/start', search }} replace />
}

// Routes below this one need a valid ?population=N param, otherwise send the user back to the picker
function RequirePopulation() {
  const { populationData } = useContext(PopulationDataContext)

  if (populationData == null) {
    return <Navigate to="/" replace />
  }

  return <Outlet />
}

function App() {
  // const theme = useTheme()
  // const isLargeScreen = useMediaQuery(theme.breakpoints.up('lg'))
  // const isMediumScreen = useMediaQuery(theme.breakpoints.down('lg'))
  // const isPastMax = useMediaQuery(theme.breakpoints.up('xl'))

  return (
    <BrowserRouter>
      <PopulationDataProvider>
        <Navbar />
        <Routes>
          <Route path='/' element={<PopulationPicker/>}/>
          <Route element={<RequirePopulation/>}>
            <Route path='/start' element={<Disclaimer/>}/>
            <Route path='/selection-panel' element={<SelectionPanel/>}/>
            <Route path='/results-dashboard' element={<ResultsDashboard/>}/>
          </Route>
          <Route path="*" element={<RedirectToStart />}/>
        </Routes>
      </PopulationDataProvider>
    </BrowserRouter>
  )
}

export default App
