import { useNavigate } from 'react-router-dom'

import Box from '@mui/material/Box'
import Card from '@mui/material/Card'
import CardContent from '@mui/material/CardContent'
import Divider from '@mui/material/Divider'
import Typography from '@mui/material/Typography'

import { populationDataDefaults } from './contexts/PopulationData'
import Button from './Button'

function PopulationPicker () {
  const navigate = useNavigate()

  const handleSelect = (populationNumber) => {
    navigate({ pathname: '/start', search: `?population=${populationNumber}` })
  }

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: '56px', padding: '40px 96px', flexGrow: 1, boxShadow: 'inset -200px 0px 60px -100px #F0F0F0' }}>
      <Box sx={{ margin: 'auto auto', paddingBottom: '10%', display: 'flex', flexDirection: 'column', gap: '40px', alignItems: 'center' }}>
        <Typography sx={{ color: '#161616', fontFamily: 'IBM Plex Sans', fontSize: '32px', fontWeight: 600 }}>
          Select a population
        </Typography>
        <Box sx={{ display: 'flex', gap: '40px', flexWrap: 'wrap', justifyContent: 'center' }}>
          {Object.entries(populationDataDefaults).map(([key, population], index) => {
            const populationNumber = key.replace('population', '')
            const characteristics = [
              ['Age', population.age],
              ['Sex', population.sex],
              ['Immigrant', population.immigrant === 'Yes' ? 'Immigrant' : 'Non-immigrant'],
              ['Hypertension', population.hypertension],
              ['Rural', population.rural]
            ]

            return (
              <Card key={key} sx={{ backgroundColor: '#FFF', border: '1px solid #00000020', borderRadius: '12px', width: '360px', boxShadow: '0px 4px 50px rgba(0, 0, 0, 0.15)' }}>
                <CardContent sx={{ display: 'flex', flexDirection: 'column', padding: '40px', gap: '18px' }}>
                  <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '24px', fontWeight: 600 }}>
                    Population {index + 1}
                  </Typography>
                  <Divider />
                  {characteristics.map(([label, value]) => (
                    <Box key={label} sx={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
                      <Typography sx={{ color: '#606060', fontFamily: 'IBM Plex Sans', fontSize: '16px', fontWeight: 400, lineHeight: '18px' }}>{label}:</Typography>
                      <Typography sx={{ color: '#000000', fontFamily: 'IBM Plex Sans', fontSize: '16px', fontWeight: 600, lineHeight: '18px' }}>{value}</Typography>
                    </Box>
                  ))}
                  <Box sx={{ display: 'flex', justifyContent: 'flex-end', marginTop: '12px' }}>
                    <Button label="Select" elevate onClick={() => handleSelect(populationNumber)} />
                  </Box>
                </CardContent>
              </Card>
            )
          })}
        </Box>
      </Box>
    </Box>
  )
}

export default PopulationPicker
