import React, { useContext, useRef, useState } from 'react'
import NavLink from './ParamNavLink'

import Box from '@mui/material/Box'
import MaterialButton from '@mui/material/Button'
import Card from '@mui/material/Card'
import CardContent from '@mui/material/CardContent'
import CheckCircleIcon from '@mui/icons-material/CheckCircle'
import ArrowForwardIosRoundedIcon from '@mui/icons-material/ArrowForwardIosRounded'
import CompareArrowsRoundedIcon from '@mui/icons-material/CompareArrowsRounded'
import HourglassEmptyRoundedIcon from '@mui/icons-material/HourglassEmptyRounded'
import InsertChartOutlinedRoundedIcon from '@mui/icons-material/InsertChartOutlinedRounded'
import ReplayRoundedIcon from '@mui/icons-material/ReplayRounded'
import Divider from '@mui/material/Divider'
import Typography from '@mui/material/Typography'

import { PopulationDataContext } from './contexts/PopulationData'
import Breadcrumb from "./Breadcrumb"
import Button from './Button'
import DropDown from './DropDown'
import PeopleGrid from './PeopleGrid'

function SelectionPanel () {
  // Population characteristics state
  const [age, setAge] = useState('')
  const [sex, setSex] = useState('')
  const [immigrant, setImmigrant] = useState('')
  const [hypertension, setHypertension] = useState('')
  const [rural, setRural] = useState('')
  // Results state
  const [results, setResults] = useState(null)
  const [isLoading, setIsLoading] = useState(false)
  const timeoutRef = useRef(null) // Ref to store the timeout ID for simulating loading state and resetting
  // Context for population data
  const { populationData } = useContext(PopulationDataContext)
  // Navigation paths
  const breadcrumbs = [
    { label: 'Start', path: '/start' },
    { label: 'Selection Panel', path: '/selection-panel' }
  ]

  // Only the option matching the population data is enabled
  const buildOptions = (values, field) => values.map((value) => ({
    value,
    state: populationData?.[field] === value ? 'enabled' : 'disabled'
  }))

  const handleChange = (event, setter) => {
    setter(event.target.value);
  }

  const handleGenerateResult = () => {
    if (timeoutRef.current) {
      window.clearTimeout(timeoutRef.current)
    }

    setIsLoading(true)
    setResults(null)

    // Scenario pre-selection
    setAge(populationData.age)
    setSex(populationData.sex)
    setImmigrant(populationData.immigrant)
    setHypertension(populationData.hypertension)
    setRural(populationData.rural)

    timeoutRef.current = window.setTimeout(() => {
      const selection = {
        age,
        sex,
        immigrant,
        hypertension,
        rural
      }

      setResults(selection)
      setIsLoading(false)
      timeoutRef.current = null
    }, 2000)
  }

  const resetSelection = () => {
    if (timeoutRef.current) {
      window.clearTimeout(timeoutRef.current)
    }

    setAge('')
    setSex('')
    setImmigrant('')
    setHypertension('')
    setRural('')
    setResults(null)
    setIsLoading(false)
  }

  const renderPopulationSelection = () => {
    return (
      <Card sx={{ backgroundColor: '#FFF', border: '1px solid #00000020', borderRadius: '12px', maxWidth: '692px', minWidth: '692px', overflowY: 'auto', display: 'flex', boxShadow: '0px 4px 50px rgba(0, 0, 0, 0.15)' }}>
        <CardContent sx={{ display: 'flex', flexDirection: 'column', padding: '40px', gap: '24px' }}>
          <Box sx={{ display: 'flex', gap: '8px' }}>
            <CheckCircleIcon sx={{ color: '#24A148' }} />
            <Typography sx={{ color: '#525252',fontFamily: 'IBM Plex Sans', fontSize: '20px', fontWeight: 400, lineHeight: '23px' }}>
              Choose population characteristics to view results. Hover over any field for more information.
            </Typography>
          </Box>
          <Typography sx={{ color: '#161616', fontFamily: 'IBM Plex Sans', fontSize: '24px', fontWeight: 400, lineHeight: '28px' }}>
            Population Characteristics
          </Typography>
          <Box sx={{ display: 'flex', flexWrap: 'wrap',justifyContent: 'space-between' }}>
            <DropDown
              label="Age (optional)"
              tooltip="Age group as obtained from administrative health records"
              defaultOption="Select an option"
              options={buildOptions([
                "18 - 30 years old",
                "31 - 40 years old",
                "41 - 50 years old",
                "51 - 60 years old",
                "61 - 70 years old",
                "71 - 80 years old",
                "81 - 90 years old",
                "91 - 100 years old",
              ], 'age')}
              onChange={(event) => handleChange(event, setAge)}
              value={age}
            />
            <DropDown
              label="Sex (optional)"
              tooltip="Sex as obtained from administrative health records"
              defaultOption="Select an option"
              options={buildOptions(["Male", "Female"], 'sex')}
              onChange={(event) => handleChange(event, setSex)}
              value={sex}
            />
            <DropDown
              label="Immigrant (optional)"
              tooltip="Immigration status obtained from IRCC data. Immigrants are landed immigrants and/or permanent residents"
              defaultOption="Select an option"
              options={buildOptions(["Yes", "No"], 'immigrant')}
              onChange={(event) => handleChange(event, setImmigrant)}
              value={immigrant}
            />
            <DropDown
              label="Hypertension (optional)"
              tooltip="Physician-diagnosed hypertension obtained from administrative health records"
              defaultOption="Select an option"
              options={buildOptions(["Yes", "No"], 'hypertension')}
              onChange={(event) => handleChange(event, setHypertension)}
              value={hypertension}
            />
            <DropDown
              label="Rural (optional)"
              tooltip="Rural or urban residential status obtained from administrative health records"
              defaultOption="Select an option"
              options={buildOptions(["Rural residence", "Urban residence"], 'rural')}
              onChange={(event) => handleChange(event, setRural)}
              value={rural}
            />
          </Box>
          <Typography sx={{ color: '#525252',fontFamily: 'IBM Plex Sans', fontSize: '20px', fontWeight: 400 }}>
            The predicted risk is for a population with an average of these characteristics, or if the population on average had these levels of risk factors.
          </Typography>
          <Divider/>
          <Box sx={{ display: 'flex', justifyContent: results ? 'space-between' : 'flex-end', alignItems: 'center', gap: '12px' }}>
            {results && (
              <MaterialButton
                onClick={resetSelection}
                disabled={isLoading}
                sx={{
                  textTransform: 'none',
                  borderRadius: '999px',
                  padding: '10px 14px',
                  minWidth: 0,
                  height: 'auto',
                  boxShadow: 'none',
                }}
                variant="text"
              >
                <Typography sx={{ borderBottom: '1px solid #474747', color: '#474747', display: 'flex', alignItems: 'center', gap: '4px', fontFamily: 'IBM Plex Sans', fontSize: '20px', fontWeight: 500 }}>
                  Reset
                <ReplayRoundedIcon sx={{ color: '#474747', fontSize: '24px' }} />
                </Typography>
              </MaterialButton>
            )}
            <Button
              label={isLoading ? 'Generating...' : 'Generate Result'}
              elevate
              onClick={handleGenerateResult}
              disabled={isLoading}
            />
          </Box>
        </CardContent>
      </Card>
    )
  }

  const renderEmptyState = () => {
    if (isLoading) {
      return (
        <Box sx={{ display: 'flex', flexBasis: '50%', flexDirection: 'column', gap: '36px', alignItems: 'center', width: '100%' }}>
          <Typography sx={{ color: '#525252', fontFamily: 'IBM Plex Sans', fontSize: '36px', fontWeight: 300, lineHeight: '46px', textAlign: 'center' }}>
            <em>Loading results...</em>
          </Typography>
        </Box>
      )
    }

    return (
      <Box sx={{ display: 'flex', flexBasis: '50%',flexDirection: 'column', gap: '36px', alignItems: 'center', width: '100%' }}>
        <HourglassEmptyRoundedIcon sx={{ color: '#B2B2B2', height: '120px', width: '120px' }} />
        <Typography sx={{ color: '#525252', fontFamily: 'IBM Plex Sans', fontSize: '36px', fontWeight: 300, lineHeight: '46px', textAlign: 'center' }}>
          <em>No results yet.</em>
          <br/>
          Select population characteristics to generate your results.
        </Typography>
      </Box>
    )
  }

  const renderResultsPreview = () => {
    const {percent, risk, likelihood } = populationData.stats

    return (
      <Box sx={{ display: 'flex', gap: '80px' }}>
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          {/* Title */}
          <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '32px', fontWeight: 600 }}>
            Results Overview
          </Typography>

          {/* Section Header */}
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: '16px', marginBottom: '24px' }}>
            <Box sx={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
              <InsertChartOutlinedRoundedIcon sx={{ height: '36px', width: '36px' }} />
              <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '24px', fontWeight: 600, whiteSpace: 'nowrap' }}>
                % of Population Expected to Develop Diabetes in 5 Years
              </Typography>
            </Box>
            <Divider sx={{ borderColor: '#D9D9D9', width: '100%' }} />
            {/* Percent Risk */}
            <Box sx={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
              <Typography sx={{ color: '#272927', fontFamily: 'Inter', fontSize: '40px', fontWeight: 600 }}>
                {percent}%
              </Typography>
              <Box sx={{ backgroundColor: risk.color, borderRadius: '4px', padding: '6px 8px' }}>
                <Typography sx={{ color: '#272927', fontFamily: 'IBM Plex Sans', fontSize: '20px', fontWeight: 400 }}>
                  {risk.label} Risk
                </Typography>
              </Box>
            </Box>
            {/* Description */}
            <Typography sx={{ fontFamily: 'Inter', fontSize: '20px', fontWeight: 400, lineHeight: '24px', maxWidth: '610px' }}>
              For the population you have identified, there is an {percent}% risk of Type 2 diabetes onset in the next 5 years.
            </Typography>
          </Box>

          {/* Section header */}
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: '16px', marginBottom: '24px' }}>
            <Box sx={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
              <CompareArrowsRoundedIcon sx={{ height: '36px', width: '36px' }} />
              <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '24px', fontWeight: 600 }}>
                Comparison to national risk
              </Typography>
            </Box>
            <Divider sx={{ borderColor: '#D9D9D9', width: '100%' }} />
            <Typography sx={{ fontFamily: 'Inter', fontSize: '20px', fontWeight: 400, lineHeight: '24px', maxWidth: '610px' }}>
              Compared to the national average of <strong>9%</strong>, individuals in this population are <strong>{likelihood}x</strong> as likely to develop diabetes.
            </Typography>
          </Box>

          {/* Graphic */}
          <Box sx={{ display: 'flex', gap: '60px' }}>
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '16px', fontWeight: 600, color: '#3E3E3E', marginBottom: '10px' }}>
                National Average
              </Typography>
            <PeopleGrid blackCount={9} yellowCount={0} totalCount={100} />
            <Typography sx={{ color: '#000', fontFamily: 'Inter', fontSize: '32px', fontWeight: 600 }}>
                9<span style={{ color: '#858585' }}>/100</span>
            </Typography>
            </Box>
            {/* This Population */}
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '16px', fontWeight: 600, color: '#3E3E3E', marginBottom: '10px' }}>
                This Population
              </Typography>
              <PeopleGrid blackCount={9} yellowCount={parseInt(percent) - 9} totalCount={100} />
              <Typography sx={{ color: '#000', fontFamily: 'Inter', fontSize: '32px', fontWeight: 600 }}>
                {percent}<span style={{ color: '#858585' }}>/100</span>
              </Typography>
            </Box>
          </Box>
        </Box>

        {/* View Full Assessment Button */}
        <Box sx={{ alignContent: 'center', flexBasis: '100%', maxWidth: '300px' }}>
          <NavLink to="/results-dashboard" style={{ textDecoration: 'none' }}>
            <Button
              label='View Full Assessment'
              icon={<ArrowForwardIosRoundedIcon sx={{ color: '#AAA', height: '36px', width: '36px' }} />}
              elevate
            />
          </NavLink>
        </Box>
      </Box>
    )
  }

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: '56px', padding: '40px 96px', flexGrow: 1, boxShadow: 'inset -200px 0px 60px -100px #F0F0F0' }}>
      <Breadcrumb breadcrumbs={breadcrumbs} />
      <Box sx={{ margin: 'auto auto', paddingBottom: '10%', display: 'flex', gap: '100px', alignItems: 'center', justifyContent: 'center', width: '100%' }}>
        {renderPopulationSelection()}
        {results
          ? renderResultsPreview()
          : renderEmptyState()
        }
      </Box>
    </Box>
  )
}

export default SelectionPanel
