import Box from '@mui/material/Box'
import FormControl from '@mui/material/FormControl'
import HelpOutlineTwoToneIcon from '@mui/icons-material/HelpOutlineTwoTone'
import MenuItem from '@mui/material/MenuItem'
import Select from '@mui/material/Select'
import Tooltip from '@mui/material/Tooltip'
import Typography from '@mui/material/Typography'

function DropDown (props) {
  const { label, tooltip, defaultOption, options, onChange, value } = props

  return (
    <FormControl variant="filled" sx={{ maxWidth: '288px', flexBasis: '50%', marginBottom: '32px' }}>
      <Box sx={{ display: 'flex' }}>
        <Tooltip title={tooltip} arrow placement="bottom-start">
          <div style={{ display: 'flex', alignItems: 'center', gap: '4px', marginBottom: '8px', borderBottom: 'dotted 1px #8D8D8D' }}>
            <Typography sx={{ color: '#525252', fontFamily: 'IBM Plex Sans', fontSize: '14px', fontWeight: 500 }}>
              {label}
            </Typography>
            <HelpOutlineTwoToneIcon sx={{ color: '#525252', height: '16px', width: '16px' }} />
          </div>
        </Tooltip>
      </Box>
      <Select
        value={value}
        onChange={onChange}
        displayEmpty
      >
        <MenuItem value="">
          <Typography sx={{ color: '#B3B3B3', fontFamily: 'IBM Plex Sans', fontSize: '16px' }}>
            {defaultOption}
          </Typography>
        </MenuItem>
        {options.map((option) => (
          <MenuItem value={option.value} key={option.value} disabled={option.state === "disabled"}>
            <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '16px' }}>
              {option.value}
            </Typography>
          </MenuItem>
        ))}
      </Select>
    </FormControl>
  )
}

export default DropDown