import React, { useContext, useState } from 'react'

import ArrowForwardRoundedIcon from '@mui/icons-material/ArrowForwardRounded'
import BatchPredictionRoundedIcon from '@mui/icons-material/BatchPredictionRounded'
import Box from '@mui/material/Box'
import Card from '@mui/material/Card'
import CardContent from '@mui/material/CardContent'
import CloseRoundedIcon from '@mui/icons-material/CloseRounded'
import Dialog from '@mui/material/Dialog'
import DialogActions from '@mui/material/DialogActions'
import DialogContent from '@mui/material/DialogContent'
import Divider from '@mui/material/Divider'
import IconButton from '@mui/material/IconButton'
import Skeleton from '@mui/material/Skeleton'
import Typography from '@mui/material/Typography'

import { PopulationDataContext } from './contexts/PopulationData'
import Button from './Button'
import BarChart from './images/BarChart.png'
import LineChart from './images/LineChart.png'
import ChartToggle from './ChartToggle'

function ActionableInsightsCard () {
  // Context for population data
  const { populationData } = useContext(PopulationDataContext)

  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const [interpretationSwitch, setInterpretationSwitch] = useState(BarChart)

  const handleSwitchChange = (event) => {
    setInterpretationSwitch(event.target.checked ? LineChart : BarChart)
  }

  if (populationData == null) {
    return (
      <Card sx={{ backgroundColor: '#FFF', border: '1px solid #00000020', borderRadius: '12px', width: '1080px', height: '375px', overflowY: 'auto', display: 'flex', boxShadow: '0px 4px 50px rgba(0, 0, 0, 0.15)' }}>
        <CardContent sx={{ display: 'flex', flexDirection: 'column', padding: '40px', width: '100%' }}>
          {/* Title */}
          <Box sx={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
            <Skeleton variant="circular" width={32} height={32} />
            <Skeleton variant="text" width={220} sx={{ fontSize: '24px' }} />
          </Box>
          <Divider sx={{ margin: '18px 0' }} />
          {/* Two paragraph columns */}
          <Box sx={{ display: 'flex', justifyContent: 'space-between', gap: '24px', flexGrow: 1 }}>
            {[0, 1].map((column) => (
              <Box key={column} sx={{ flex: 1 }}>
                <Skeleton variant="text" sx={{ fontSize: '18px' }} />
                <Skeleton variant="text" sx={{ fontSize: '18px' }} />
                <Skeleton variant="text" sx={{ fontSize: '18px' }} />
                <Skeleton variant="text" sx={{ fontSize: '18px' }} />
                <Skeleton variant="text" width="60%" sx={{ fontSize: '18px' }} />
              </Box>
            ))}
          </Box>
          {/* More button */}
          <Box sx={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center' }}>
            <Skeleton variant="rounded" width={100} height={40} />
          </Box>
        </CardContent>
      </Card>
    )
  }

  const { percent, likelihood } = populationData.stats

  const renderDialog = () => {
    return (
      <Dialog open={isDialogOpen} onClose={() => setIsDialogOpen(false)} maxWidth="xxl" fullWidth>
        <IconButton
          aria-label="Close actionable insights"
          onClick={() => setIsDialogOpen(false)}
          sx={{ color: '#000', position: 'absolute', top: 16, right: 16, zIndex: 1 }}
        >
          <CloseRoundedIcon />
        </IconButton>
        <DialogContent sx={{ padding: '40px' }}>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
            {/* Title */}
            <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '32px', fontWeight: 600, marginBottom: '40px' }}>
              Actionable Insights
            </Typography>
            <Box sx={{ display: 'flex', gap: '80px' }}>
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: '18px', maxWidth: '550px' }}>
                <Box sx={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                  <BatchPredictionRoundedIcon sx={{ height: '32px', width: '32px' }} />
                  <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '24px', fontWeight: 600, whiteSpace: 'nowrap' }}>Interpretation</Typography>
                </Box>
                <Divider />
                <Typography component="div" sx={{ color: '#161616', fontFamily: 'IBM Plex Sans', fontSize: '18px', lineHeight: '26px', marginBottom: '40px' }}>
                  <ul>
                    <li style={{ marginBottom: '16px' }}>
                      For this group (those matching the clinical indicators selected), there is an {percent}% risk of developing type 2 diabetes by 2030
                    </li>
                    <li>
                      Compared to the national average of 9%, those in this population are {likelihood}x as likely to develop diabetes
                    </li>
                  </ul>
                </Typography>
                <Box sx={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                  <BatchPredictionRoundedIcon sx={{ height: '32px', width: '32px' }} />
                  <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '24px', fontWeight: 600, whiteSpace: 'nowrap' }}>Implications</Typography>
                </Box>
                <Divider />
                <Typography sx={{ color: '#161616', fontFamily: 'IBM Plex Sans', fontSize: '18px', lineHeight: '26px', flex: 1 }}>
                  With one of the higher type 2 diabetes onset risks in Peel Region, this population develops diabetes at a higher rate than the average Peel Region resident, or other population groups. This population would benefit from additional resources, care opportunities, and education regarding type 2 diabetes.
                </Typography>
                <Typography sx={{ color: '#161616', fontFamily: 'IBM Plex Sans', fontSize: '18px', lineHeight: '26px', flex: 1 }}>
                  If you are a policymaker involved in public health planning, chronic disease prevention, or community health programming, we recommend prioritizing targeted outreach initiatives, culturally tailored health education, and improved access to screening and preventive care services.
                </Typography>
              </Box>

              <Box sx={{ display: 'flex', flexDirection: 'column', gap: '18px', flex: 1 }}>
                <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                  <ChartToggle checked={interpretationSwitch === LineChart} onChange={handleSwitchChange} />
                </Box>
                <Box sx={{ position: 'relative', width: '100%' }}>
                  <Box
                    component="img"
                    src={BarChart}
                    alt="Bar chart interpretation"
                    sx={{
                      display: 'block',
                      width: '100%',
                      opacity: interpretationSwitch === BarChart ? 1 : 0,
                      transition: 'opacity 300ms ease-in-out',
                    }}
                  />
                  <Box
                    component="img"
                    src={LineChart}
                    alt="Line chart interpretation"
                    sx={{
                      position: 'absolute',
                      inset: 0,
                      display: 'block',
                      width: '100%',
                      opacity: interpretationSwitch === LineChart ? 1 : 0,
                      transition: 'opacity 300ms ease-in-out',
                    }}
                  />
                </Box>
              </Box>
            </Box>
          </Box>
        </DialogContent>
        <DialogActions sx={{ padding: '0 40px 32px' }}>
          <Button label="Back" elevate onClick={() => setIsDialogOpen(false)} />
        </DialogActions>
      </Dialog>
    )
  }

  return (
    <>
      {renderDialog()}
      <Card sx={{ backgroundColor: '#FFF', border: '1px solid #00000020', borderRadius: '12px', width: '1080px', height: '375px', overflowY: 'auto', display: 'flex', boxShadow: '0px 4px 50px rgba(0, 0, 0, 0.15)' }}>
        <CardContent sx={{ display: 'flex', flexDirection: 'column', padding: '40px' }}>
          <Box sx={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
            <BatchPredictionRoundedIcon sx={{ height: '32px', width: '32px' }} />
            <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '24px', fontWeight: 600, whiteSpace: 'nowrap' }}>Actionable Insights</Typography>
          </Box>
          <Divider sx={{ margin: '18px 0' }} />
          <Box sx={{ display: 'flex', justifyContent: 'space-between', flexGrow: 1 }}>
            <Typography sx={{ color: '#161616', fontFamily: 'IBM Plex Sans', fontSize: '18px', fontWeight: 400 }}>
              With one of the higher type 2 diabetes onset risks in Peel Region, this population develops diabetes at a higher rate than the average Peel Region resident, or other population groups. This population would benefit from additional resources, care opportunities, and education regarding type 2 diabetes.
            </Typography>
            <Typography sx={{ color: '#161616', fontFamily: 'IBM Plex Sans', fontSize: '18px', fontWeight: 400 }}>
              If you are a policymaker involved in public health planning, chronic disease prevention, or community health programming, we recommend prioritizing targeted outreach initiatives, culturally tailored health education, and improved access to screening and preventive care services.
            </Typography>
          </Box>
          <Box sx={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', gap: '12px' }}>
            <Button label="More" icon={<ArrowForwardRoundedIcon sx={{ height: '36px', width: '36px' }} />} onClick={() => setIsDialogOpen(true)} style={{ padding: '0 8px', minWidth: 'auto' }} />
          </Box>
        </CardContent>
      </Card>
    </>
  )
}

export default ActionableInsightsCard
