import React, { useContext, useState } from 'react'

import BatchPredictionRoundedIcon from '@mui/icons-material/BatchPredictionRounded'
import Box from '@mui/material/Box'
import Card from '@mui/material/Card'
import CardContent from '@mui/material/CardContent'
import Divider from '@mui/material/Divider'
import Skeleton from '@mui/material/Skeleton'
import Typography from '@mui/material/Typography'

import { PopulationDataContext } from './contexts/PopulationData'
import BarChart from './images/BarChart.png'
import LineChart from './images/LineChart.png'
import ChartToggle from './ChartToggle'

function InterpretationCard () {
  // Context for population data
  const { populationData } = useContext(PopulationDataContext)

  const [interpretationSwitch, setInterpretationSwitch] = useState(BarChart)
  const isLineChart = interpretationSwitch === LineChart

  const handleSwitchChange = (event) => {
    setInterpretationSwitch(event.target.checked ? LineChart : BarChart)
  }

  if (populationData == null) {
    return (
      <Card sx={{ backgroundColor: '#FFF', border: '1px solid #00000020', borderRadius: '12px', width: '1080px', height: '718px', overflowY: 'auto', display: 'flex', boxShadow: '0px 4px 50px rgba(0, 0, 0, 0.15)' }}>
        <CardContent sx={{ display: 'flex', flexDirection: 'column', padding: '40px', width: '100%' }}>
          {/* Title */}
          <Box sx={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
            <Skeleton variant="circular" width={32} height={32} />
            <Skeleton variant="text" width={160} sx={{ fontSize: '24px' }} />
          </Box>
          <Divider sx={{ margin: '18px 0' }} />
          {/* Chart toggle */}
          <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', marginBottom: '24px' }}>
            <Skeleton variant="rounded" width={220} height={40} />
          </Box>
          {/* Chart (935 x 357) */}
          <Skeleton variant="rounded" width="100%" height="auto" sx={{ aspectRatio: '935 / 357' }} />
          {/* Interpretation bullets */}
          <Box sx={{ marginTop: '24px' }}>
            <Skeleton variant="text" sx={{ fontSize: '18px' }} />
            <Skeleton variant="text" width="70%" sx={{ fontSize: '18px' }} />
            <Skeleton variant="text" width="85%" sx={{ fontSize: '18px' }} />
          </Box>
        </CardContent>
      </Card>
    )
  }
  const { percent, likelihood } = populationData.stats

  return (
    <Card sx={{ backgroundColor: '#FFF', border: '1px solid #00000020', borderRadius: '12px', width: '1080px', height: '718px', overflowY: 'auto', display: 'flex', boxShadow: '0px 4px 50px rgba(0, 0, 0, 0.15)' }}>
      <CardContent sx={{ display: 'flex', flexDirection: 'column', padding: '40px', width: '100%' }}>
        <Box sx={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
          <BatchPredictionRoundedIcon sx={{ height: '32px', width: '32px' }} />
          <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '24px', fontWeight: 600, whiteSpace: 'nowrap' }}>
            Interpretation
          </Typography>
        </Box>
        <Divider sx={{ margin: '18px 0' }} />
        <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', marginBottom: '24px' }}>
          <ChartToggle checked={isLineChart} onChange={handleSwitchChange} />
        </Box>
        <Box sx={{ position: 'relative', width: '100%' }}>
          <Box component="img" src={BarChart} alt="Bar chart interpretation" sx={{ display: 'block', width: '100%', opacity: isLineChart ? 0 : 1, transition: 'opacity 300ms ease-in-out' }} />
          <Box component="img" src={LineChart} alt="Line chart interpretation" sx={{ position: 'absolute', inset: 0, display: 'block', width: '100%', opacity: isLineChart ? 1 : 0, transition: 'opacity 300ms ease-in-out' }} />
        </Box>
        <Typography component="div" sx={{ color: '#161616', fontFamily: 'IBM Plex Sans', fontSize: '18px', fontWeight: 400, marginTop: '24px' }}>
          <ul>
            <li>For this group (those matching the indicators selected), the estimated risk of developing type 2 diabetes by 2030 is approximately {percent}%, with a likely range of {parseInt(percent) - 3}% to {parseInt(percent) + 3}%.</li>
            <li>Compared to the national average of 9%, those in this population are {likelihood}x as likely to develop diabetes</li>
          </ul>
        </Typography>
      </CardContent>
    </Card>
  )
}

export default InterpretationCard
