import React, { createContext, useMemo } from 'react'
import { useSearchParams } from 'react-router-dom'

export const PopulationDataContext = createContext(null)
PopulationDataContext.displayName = 'PopulationDataContext' // Show context name in React Dev Tools

export const populationDataDefaults = {
  population1: {
    age: '51 - 60 years old',
    sex: 'Female',
    immigrant: 'Yes',
    hypertension: 'No',
    rural: 'Urban residence',
    stats: {
      percent: '18',
      risk: {
        label: 'High',
        color: '#FCD6B0',
      },
      likelihood: '2'
    }
  },
  population2: {
    age: '31 - 40 years old',
    sex: 'Male',
    immigrant: 'No',
    hypertension: 'Yes',
    rural: 'Urban residence',
    stats: {
      percent: '11',
      risk: {
        label: 'Moderate',
        color: '#FCEBB0',
      },
      likelihood: '1.2'
    }
  },
  population3: {
    age: '51 - 60 years old',
    sex: 'Male',
    immigrant: 'No',
    hypertension: 'No',
    rural: 'Urban residence',
    stats: {
      percent: '14',
      risk: {
        label: 'Moderate',
        color: '#FCEBB0',
      },
      likelihood: '1.6'
    }
  }
}

// The population context comes from the ?population=N URL param; it is null when the param is missing or invalid
const PopulationDataProvider = ({ children }) => {
  const [searchParams] = useSearchParams()
  const populationParam = searchParams.get('population')

  const defaultContext = useMemo(() => {
    const populationKey = `population${populationParam}`
    const populationData = Object.hasOwn(populationDataDefaults, populationKey)
      ? populationDataDefaults[populationKey]
      : null

    return { populationData }
  }, [populationParam])

  return (
    <PopulationDataContext.Provider value={defaultContext}>
      {children}
    </PopulationDataContext.Provider>
  )
}

export default PopulationDataProvider
