import * as React from 'react'
import Box from '@mui/material/Box'
import PersonFullBlack from './images/PersonFullBlack.svg'
import PersonFullYellow from './images/PersonFullYellow.svg'

function PeopleGrid({ blackCount, yellowCount, totalCount }) {
  if (totalCount <= 0) {
    return null
  }

  const safeBlackCount = Math.min(Math.max(Math.floor(blackCount), 0), totalCount)
  const safeYellowCount = Math.min(
    Math.max(Math.floor(yellowCount), 0),
    totalCount - safeBlackCount
  )
  const columns = totalCount === 100 ? 20 : Math.ceil(Math.sqrt(totalCount))

  const people = Array.from({ length: totalCount }, (_, index) => {
    if (index < safeBlackCount) {
      return 'black'
    }

    if (index < safeBlackCount + safeYellowCount) {
      return 'yellow'
    }

    return 'empty'
  })

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '16px' }}>
      <Box
        sx={{
          display: 'grid',
          gridTemplateColumns: `repeat(${columns}, minmax(0, 15px))`,
          gridTemplateRows: `repeat(5, minmax(0, 39px))`,
          gap: '5px',
          alignItems: 'center',
          justifyContent: 'center',
        }}
      >
        {people.map((status, index) => {
          return (
            <Box
              key={index}
              component="img"
              src={status === 'yellow' ? PersonFullYellow : PersonFullBlack}
              alt="person"
              sx={{
                width: '14.55px',
                height: '36.38px',
                display: 'block',
                opacity: status === 'empty' ? 0.32 : 1,
              }}
            />
          )
        })}
      </Box>
    </Box>
  )
}

export default PeopleGrid
