import NavLink from './ParamNavLink'

import Box from '@mui/material/Box'
import KeyboardDoubleArrowDownIcon from '@mui/icons-material/KeyboardDoubleArrowDown'
import Typography from '@mui/material/Typography'

export default function Breadcrumbs(props) {
  const breadcrumbs = props.breadcrumbs || []
  const overflow = props.overflow || false
  const actions = props.actions || []

  return (
    <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
      <Box sx={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
        {breadcrumbs.map((breadcrumb, index) => (
          <Box key={index} sx={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <NavLink to={breadcrumb.path} style={{ textDecoration: 'none' }}>
              <Typography sx={{ color: '#0F62FE', fontFamily: 'IBM Plex Sans', fontSize: '25px', fontWeight: 'regular' }}>
                {breadcrumb.label}
              </Typography>
            </NavLink>
            <Typography sx={{ color: '#161616', fontFamily: 'IBM Plex Sans', fontSize: '14px', fontWeight: 'regular' }}>/</Typography>
          </Box>
        ))}
      </Box>
      {overflow &&
        (
          <Box sx={{ display: 'flex', alignItems: 'center', gap: '8px', overflowX: 'auto' }}>
            <KeyboardDoubleArrowDownIcon sx={{ color: '#777', height: '20px' }} />
            <Typography sx={{ color: '#777', fontFamily: 'IBM Plex Sans', fontSize: '18px', fontWeight: 'regular' }}>
              Scroll down for More
            </Typography>
            <KeyboardDoubleArrowDownIcon sx={{ color: '#777', height: '20px' }} />
          </Box>
        )
      }
      {actions.length > 0 && actions.map((action, index) => (
        <Box key={index} sx={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          {action}
        </Box>
      ))}
    </Box>
  )
}
