import Button from '@mui/material/Button'

function CustomButton (props) {
  const { label, icon, elevate, onClick, disabled = false, style } = props

  return (
    <Button
      variant="text"
      type="button"
      onClick={onClick}
      disabled={disabled}
      sx={{
        display: 'flex',
        alignItems: 'center',
        color: '#474747',
        fontSize: '20px',
        fontWeight: 500,
        lineHeight: '22px',
        textTransform: 'none',
        borderRadius: '20px',
        boxShadow: elevate ? '0px 4px 50px rgba(0, 0, 0, 0.15)' : '',
        padding: '20px 30px',
        minWidth: '166px',
        whiteSpace: 'nowrap',
        ...style
      }}
      endIcon={icon}
    >
      {label}
    </Button>
  )
}

export default CustomButton