import React, { useContext, useState } from 'react'

import ArrowForwardRoundedIcon from '@mui/icons-material/ArrowForwardRounded'
import Box from '@mui/material/Box'
import Card from '@mui/material/Card'
import CardContent from '@mui/material/CardContent'
import CloseRoundedIcon from '@mui/icons-material/CloseRounded'
import CompareArrowsRoundedIcon from '@mui/icons-material/CompareArrowsRounded'
import Dialog from '@mui/material/Dialog'
import DialogActions from '@mui/material/DialogActions'
import DialogContent from '@mui/material/DialogContent'
import Divider from '@mui/material/Divider'
import IconButton from '@mui/material/IconButton'
import Skeleton from '@mui/material/Skeleton'
import Typography from '@mui/material/Typography'

import { PopulationDataContext } from './contexts/PopulationData'
import Button from './Button'
import PeopleGrid from './PeopleGrid'

function ComparisonCard () {
  // Context for population data
  const { populationData } = useContext(PopulationDataContext)

  const [isDialogOpen, setIsDialogOpen] = useState(false)

  if (populationData == null) {
    return (
      <Card sx={{ backgroundColor: '#FFF', border: '1px solid #00000020', borderRadius: '12px', width: '575px', height: '375px', overflowY: 'auto', display: 'flex', boxShadow: '0px 4px 50px rgba(0, 0, 0, 0.15)' }}>
        <CardContent sx={{ display: 'flex', flexDirection: 'column', padding: '40px', width: '100%' }}>
          <Box sx={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
            <Skeleton variant="circular" width={32} height={32} />
            <Skeleton variant="text" width={340} sx={{ fontSize: '24px' }} />
          </Box>
          <Divider sx={{ margin: '18px 0' }} />
          <Box sx={{ display: 'flex', flexDirection: 'column', justifyContent: 'space-between', flexGrow: 1 }}>
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: '12px', marginBottom: '22px' }}>
              <Skeleton variant="text" width={120} sx={{ fontSize: '16px' }} />
              <Box sx={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
                <Skeleton variant="rounded" width={40} height={32} />
                <Skeleton variant="text" width={80} sx={{ fontSize: '32px' }} />
              </Box>
            </Box>
            <Box>
              <Skeleton variant="text" width={120} sx={{ fontSize: '16px' }} />
              <Box sx={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
                <Skeleton variant="rounded" width={40} height={32} />
                <Skeleton variant="text" width={80} sx={{ fontSize: '32px' }} />
              </Box>
            </Box>
          </Box>
          <Box sx={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center' }}>
            <Skeleton variant="rounded" width={100} height={40} />
          </Box>
        </CardContent>
      </Card>
    )
  }

  const { percent, risk, likelihood } = populationData.stats

  const renderDialog = () => {
    return (
      <Dialog open={isDialogOpen} onClose={() => setIsDialogOpen(false)} maxWidth="xl" fullWidth>
        <IconButton
          aria-label="Close comparison"
          onClick={() => setIsDialogOpen(false)}
          sx={{ color: '#000', position: 'absolute', top: 16, right: 16, zIndex: 1 }}
        >
          <CloseRoundedIcon />
        </IconButton>
        <DialogContent sx={{ padding: '40px' }}>
          <Box sx={{ display: 'flex', gap: '80px' }}>
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: '16px', flex: 1 }}>
              {/* Title */}
              <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '32px', fontWeight: 600, marginBottom: '40px' }}>
                Comparison to National Risk
              </Typography>
              <Box sx={{ display: 'flex', gap: '80px' }}>
                {/* Risk Level Comparison Left */}
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: '16px', flex: 1 }}>
                  <Box sx={{ display: 'flex', flexDirection: 'column', gap: '16px', marginBottom: '24px' }}>
                    <Box sx={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                      <CompareArrowsRoundedIcon sx={{ height: '36px', width: '36px' }} />
                      <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '24px', fontWeight: 600 }}>
                        Risk level compared to national baseline
                      </Typography>
                    </Box>
                    <Divider sx={{ borderColor: '#D9D9D9' }} />
                    <Typography sx={{ fontFamily: 'Inter', fontSize: '20px', lineHeight: '24px' }}>
                      Compared to the national average of <strong>9%</strong>, individuals in this group are <strong>{likelihood}x</strong> as likely to develop type 2 diabetes. This increased risk indicates a potential need for targeted public health strategies for this population group. If unaddressed, elevated risk levels in this population may lead to increased demand for diabetes-related healthcare resources.
                    </Typography>
                  </Box>
                  <Box sx={{ display: 'flex', gap: '60px' }}>
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                      <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '18px', fontWeight: 600, color: '#3E3E3E' }}>National Average</Typography>
                      <Box sx={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
                        <Typography sx={{ color: '#000', fontFamily: 'Inter', fontSize: '32px', fontWeight: 600 }}>9<span style={{ color: '#858585' }}>/100</span></Typography>
                        <Box sx={{ backgroundColor: '#FCEBB0', borderRadius: '4px', padding: '6px 8px' }}>
                          <Typography sx={{ color: '#272927', fontFamily: 'IBM Plex Sans', fontSize: '14px', fontWeight: 500 }}>Moderate Risk</Typography>
                        </Box>
                      </Box>
                      <PeopleGrid blackCount={9} yellowCount={0} totalCount={100} />
                    </Box>
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                      <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '18px', fontWeight: 600, color: '#3E3E3E' }}>This Population</Typography>
                      <Box sx={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
                        <Typography sx={{ color: '#000', fontFamily: 'Inter', fontSize: '32px', fontWeight: 600 }}>
                          {percent}<span style={{ color: '#858585' }}>/100</span>
                        </Typography>
                        <Box sx={{ backgroundColor: risk.color, borderRadius: '4px', padding: '6px 8px' }}>
                          <Typography sx={{ color: '#272927', fontFamily: 'IBM Plex Sans', fontSize: '14px', fontWeight: 500 }}>{risk.label} Risk</Typography>
                        </Box>
                      </Box>
                      <PeopleGrid blackCount={9} yellowCount={parseInt(percent) - 9} totalCount={100} />
                    </Box>
                  </Box>
                </Box>
                {/* Legend Right */}
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: '24px', backgroundColor: '#F9F9F9', borderRadius: '12px', padding: '24px', height: 'fit-content', maxWidth: '464px' }}>
                  <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '18px', fontWeight: 600, marginBottom: '16px' }}>What do the risk levels mean?</Typography>
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: '8px', alignItems: 'center' }}>
                      <Box sx={{ backgroundColor: '#E5FCB0', borderRadius: '4px', padding: '6px 8px' }}>
                        <Typography sx={{ color: '#272927', fontFamily: 'IBM Plex Sans', fontSize: '14px', fontWeight: 500 }}>Low Risk</Typography>
                      </Box>
                      <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '14px', fontWeight: 500, color: '#000' }}>
                        {'< 5%'}
                      </Typography>
                    </Box>
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: '8px', alignItems: 'center' }}>
                      <Box sx={{ backgroundColor: '#FCEBB0', borderRadius: '4px', padding: '6px 8px' }}>
                        <Typography sx={{ color: '#272927', fontFamily: 'IBM Plex Sans', fontSize: '14px', fontWeight: 500 }}>Moderate Risk</Typography>
                      </Box>
                      <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '14px', fontWeight: 500, color: '#000' }}>
                        5% - 14%
                      </Typography>
                    </Box>
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: '8px', alignItems: 'center' }}>
                      <Box sx={{ backgroundColor: '#FCD6B0', borderRadius: '4px', padding: '6px 8px' }}>
                        <Typography sx={{ color: '#272927', fontFamily: 'IBM Plex Sans', fontSize: '14px', fontWeight: 500 }}>High Risk</Typography>
                      </Box>
                      <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '14px', fontWeight: 500, color: '#000' }}>
                        15% - 29%
                      </Typography>
                    </Box>
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: '8px', alignItems: 'center' }}>
                      <Box sx={{ backgroundColor: '#FFBC92', borderRadius: '4px', padding: '6px 8px' }}>
                        <Typography sx={{ color: '#272927', fontFamily: 'IBM Plex Sans', fontSize: '14px', fontWeight: 500 }}>Very High Risk</Typography>
                      </Box>
                      <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '14px', fontWeight: 500, color: '#000' }}>
                        {'> 30%'}
                      </Typography>
                    </Box>
                  </Box>
                  <Typography sx={{ fontFamily: 'Inter', fontSize: '18px', lineHeight: '22px', fontWeight: 400, color: '#000' }}>
                    For example, populations that have factors such as younger age, female sex, long-term residency (non-immigrant), living in urban areas, and no history of hypertension, show a low risk for developing type 2 diabetes.
                  </Typography>
                </Box>
              </Box>
            </Box>
          </Box>
        </DialogContent>
        <DialogActions sx={{ padding: '0 40px 32px' }}>
          <Button label="Back" elevate onClick={() => setIsDialogOpen(false)} />
        </DialogActions>
      </Dialog>
    )
  }

  return (
    <>
      {renderDialog()}
      <Card sx={{ backgroundColor: '#FFF', border: '1px solid #00000020', borderRadius: '12px', width: '575px', height: '375px', overflowY: 'auto', display: 'flex', boxShadow: '0px 4px 50px rgba(0, 0, 0, 0.15)' }}>
        <CardContent sx={{ display: 'flex', flexDirection: 'column', padding: '40px', width: '100%' }}>
          <Box sx={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
            <CompareArrowsRoundedIcon sx={{ height: '32px', width: '32px' }} />
            <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '24px', fontWeight: 600, whiteSpace: 'nowrap' }}>
              Comparison to National Risk
            </Typography>
          </Box>
          <Divider sx={{ margin: '18px 0' }} />
          <Box sx={{ display: 'flex', flexDirection: 'column', justifyContent: 'space-between', flexGrow: 1 }}>
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: '12px', marginBottom: '22px' }}>
              <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '16px', fontWeight: 600, lineHeight: '20px', color: '#000' }}>
                This Population
              </Typography>
              <Box sx={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
                <Typography sx={{ color: '#000', fontFamily: 'Inter', fontSize: '32px', fontWeight: 600 }}>
                  {percent}%
                </Typography>
                <Box sx={{ backgroundColor: risk.color, borderRadius: '4px', padding: '6px 8px' }}>
                  <Typography sx={{ color: '#272927', fontFamily: 'IBM Plex Sans', fontSize: '14px', fontWeight: 500 }}>
                    {risk.label} Risk
                  </Typography>
                </Box>
              </Box>
            </Box>
            <Box>
              <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '16px', fontWeight: 600, lineHeight: '20px', color: '#000' }}>National Average</Typography>
              <Box sx={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
                <Typography sx={{ color: '#000', fontFamily: 'Inter', fontSize: '32px', fontWeight: 600 }}>
                  9%
                </Typography>
                <Box sx={{ backgroundColor: '#FCEBB0', borderRadius: '4px', padding: '6px 8px' }}>
                  <Typography sx={{ color: '#272927', fontFamily: 'IBM Plex Sans', fontSize: '14px', fontWeight: 500 }}>
                    Moderate Risk
                  </Typography>
                </Box>
              </Box>
            </Box>
          </Box>
          <Box sx={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', gap: '12px' }}>
            <Button label="More" icon={<ArrowForwardRoundedIcon sx={{ height: '36px', width: '36px' }} />} onClick={() => setIsDialogOpen(true)} style={{ padding: '0 8px', minWidth: 'auto' }} />
          </Box>
        </CardContent>
      </Card>
    </>
  )
}

export default ComparisonCard
