import React, { useContext } from 'react'

import Box from '@mui/material/Box'
import Card from '@mui/material/Card'
import CardContent from '@mui/material/CardContent'
import Divider from '@mui/material/Divider'
import InsertChartOutlinedRoundedIcon from '@mui/icons-material/InsertChartOutlinedRounded'
import Skeleton from '@mui/material/Skeleton'
import Typography from '@mui/material/Typography'

import { PopulationDataContext } from './contexts/PopulationData'
import Button from './Button'
import GraphPreview from './images/GraphLinearPreview.png'
import NavLink from './ParamNavLink'

function PopulationSelectionCard () {
  // Context for population data
  const { populationData } = useContext(PopulationDataContext)

  if (populationData == null) {
    return (
      <Card sx={{ backgroundColor: '#FFF', border: '1px solid #00000020', borderRadius: '12px', width: '575px', height: '718px', overflowY: 'auto', display: 'flex', boxShadow: '0px 4px 50px rgba(0, 0, 0, 0.15)' }}>
        <CardContent sx={{ display: 'flex', flexDirection: 'column', padding: '40px', gap: '18px', width: '100%' }}>
          {/* Title */}
          <Box sx={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
            <Skeleton variant="circular" width={32} height={32} />
            <Skeleton variant="text" width={320} sx={{ fontSize: '24px' }} />
          </Box>
          <Divider/>
          {/* Percent and risk label */}
          <Box sx={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
            <Skeleton variant="text" width={90} sx={{ fontSize: '40px' }} />
            <Skeleton variant="rounded" width={90} height={28} />
          </Box>
          {/* Graph preview (480 x 51) */}
          <Skeleton variant="rounded" width={480} height={51} />
          {/* Description */}
          <Box>
            <Skeleton variant="text" sx={{ fontSize: '18px' }} />
            <Skeleton variant="text" sx={{ fontSize: '18px' }} />
            <Skeleton variant="text" width="60%" sx={{ fontSize: '18px' }} />
          </Box>
          {/* Selected population characteristics */}
          <Box sx={{ display: 'flex', gap: '28px', alignItems: 'center', flexWrap: 'wrap', marginTop: '70px', marginBottom: '28px' }}>
            {Array.from({ length: 5 }).map((_, index) => (
              <Box key={index} sx={{ display: 'flex', flexDirection: 'column', gap: '8px', width: '146px', height: '77px' }}>
                <Skeleton variant="text" width={80} sx={{ fontSize: '18px' }} />
                <Divider/>
                <Skeleton variant="text" width={110} sx={{ fontSize: '16px', marginTop: '8px' }} />
              </Box>
            ))}
          </Box>
          {/* Edit button */}
          <Box sx={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center' }}>
            <Skeleton variant="rounded" width={120} height={56} />
          </Box>
        </CardContent>
      </Card>
    )
  }

  const selectedPopulation = [
    ['Age', populationData.age],
    ['Sex', populationData.sex],
    ['Immigrant', populationData.immigrant === 'Yes' ? 'Immigrant' :  'Non-immigrant'],
    ['Hypertension', populationData.hypertension],
    ['Rural', populationData.rural]
  ]
  const { percent, risk } = populationData.stats

  return (
    <Card sx={{ backgroundColor: '#FFF', border: '1px solid #00000020', borderRadius: '12px', width: '575px', height: '718px', overflowY: 'auto', display: 'flex', boxShadow: '0px 4px 50px rgba(0, 0, 0, 0.15)' }}>
      <CardContent sx={{ display: 'flex', flexDirection: 'column', padding: '40px', gap: '18px' }}>
        <Box sx={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
          <InsertChartOutlinedRoundedIcon sx={{ height: '32px', width: '32px' }} />
          <Typography sx={{ fontFamily: 'IBM Plex Sans', fontSize: '24px', fontWeight: 600, whiteSpace: 'nowrap' }}>
            Population Onset Risk Result
          </Typography>
        </Box>
        <Divider/>
        <Box sx={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
          <Typography sx={{ color: '#272927', fontFamily: 'IBM Plex Sans', fontSize: '40px', fontWeight: 600 }}>{percent}%</Typography>
          <Box sx={{ backgroundColor: risk.color, borderRadius: '4px', padding: '6px 8px' }}>
            <Typography sx={{ color: '#272927', fontFamily: 'IBM Plex Sans', fontSize: '12px', fontWeight: 600 }}>{risk.label} Risk</Typography>
          </Box>
        </Box>
        <img src={GraphPreview} alt="Graph Preview" />
        <Typography sx={{ color: '#161616', fontFamily: 'IBM Plex Sans', fontSize: '18px', fontWeight: 400 }}>
          The population you have specified indicate some risk factors that increase the likelihood of developing type 2 diabetes.
        </Typography>
        <Box sx={{ display: 'flex', gap: '28px', alignItems: 'center', flexWrap: 'wrap', marginTop: '70px', marginBottom: '28px' }}>
          {selectedPopulation.map((item, index) => (
            <Box key={index} sx={{ display: 'flex', flexDirection: 'column', gap: '8px', width: '146px', height: '77px' }}>
              <Typography sx={{ color: '#606060', fontFamily: 'IBM Plex Sans', fontSize: '18px', fontWeight: 400, lineHeight: '18px' }}>{item[0]}:</Typography>
              <Divider/>
              <Typography sx={{ color: '#000000', fontFamily: 'IBM Plex Sans', fontSize: '16px', fontWeight: 600, lineHeight: '18px', marginTop: '8px' }}>{item[1]}</Typography>
            </Box>
          ))}
        </Box>
        <Box sx={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', gap: '12px' }}>
          <NavLink to="/selection-panel" style={{ textDecoration: 'none' }}>
            <Button label="Edit" elevate />
          </NavLink>
        </Box>
      </CardContent>
    </Card>
  )
}

export default PopulationSelectionCard
